<?php declare(strict_types=1);require __DIR__.'/../src/bootstrap.php';use Kulturhus\Verein\{Database,ClubMailings};$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','A');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('board','a','members',1),('member','a','member',0);INSERT INTO contacts(id,club_id,kind,name,email,address) VALUES('a','a','person','One','shared@example.invalid','Street 1'),('b','a','person','Two','shared@example.invalid','Street 1')");function ok($b,$m){if(!$b)throw new RuntimeException($m);echo "PASS $m\n";}function denied($f,$m){try{$f();}catch(DomainException){ok(true,$m);return;}throw new RuntimeException($m);}$s=new ClubMailings($db,'board');$id=$s->save('','Subject','Message',['a','b'],bin2hex(random_bytes(16)));$p=$s->preview($id);ok(count($p['recipients'])===1&&str_contains($p['recipients'][0]['body'],'One, Two'),'family deduplication and greeting');denied(fn()=>(new ClubMailings($db,'member'))->get($id),'members cannot read outbox');putenv('VEREIN_MODE=synthetic');denied(fn()=>$s->queue($id,$p['mailing']['preview_hash']),'local send blocked');foreach(['KULTURHUS_LOCAL_DEMO','KULTURHUS_DISABLE_MAIL','APP_ENV','VEREIN_MODE'] as $key)putenv($key);putenv('APP_URL=https://example.invalid');putenv('VEREIN_PUBLIC_URL=https://example.invalid');$s->queue($id,$p['mailing']['preview_hash']);$calls=0;$sent=ClubMailings::dispatch($db,'https://example.invalid',function()use(&$calls){$calls++;});ok($sent===1&&$calls===1,'one delivery through isolated test callback');ok(ClubMailings::dispatch($db,'https://example.invalid',fn()=>throw new RuntimeException())===0,'no automatic repeat');$id=$s->save('','Other','Text',['a'],bin2hex(random_bytes(16)));$s->queue($id,$s->get($id)['preview_hash']);ClubMailings::dispatch($db,'https://example.invalid',fn()=>throw new RuntimeException('Uncertain'));ok($s->deliveries($id)[0]['state']==='uncertain','uncertain result retained without retry');
